                    else
                    {
                        string currentRow = mainFooter;
                        TemplateHandler.ReplaceBlock(ref currentRow, "sub-footer2", row);
                        mainFooterDetail.Append(currentRow);
                        if (index == arrCurrs.Length - 1)
                        {
